select id
from dm_exec_auto_task
where auto_exec_job_id = #{jobId}
  and status in ('WAIT_EXEC','FAILED','ROLLBACK')
  and exec_order  >  #{afterExecOrder}
order by exec_order
limit #{batchSize}

